using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Ads;
using MiniFramework.Platform;
using MiniFramework.Providers.PlatformMock;
using MiniFramework.Providers.AdsMock;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
public sealed class AdsServiceTests
{
    static OperationContext Wait=>OperationContext.Unlimited();static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    static ClaimOwnerSnapshot Owner=>new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,"install-A",1,"local.a");
    static FrameworkError Error(string code,ErrorKind kind=ErrorKind.Provider)=>new FrameworkError(kind,code,"injected-private-message");
    static RewardedAdRequest Request(string claim="claim-A",ClaimOwnerSnapshot? owner=null,bool user=true)=>new RewardedAdRequest("revive",claim,owner??Owner,user);
    static PlatformCapabilities Caps(CapabilitySupport support=CapabilitySupport.Supported,CapabilityAvailability availability=CapabilityAvailability.Available)=>new PlatformCapabilities(new[]{new PlatformCapability(PlatformFeature.Lifecycle,CapabilitySupport.Supported,CapabilityAvailability.Available,"mock.lifecycle"),new PlatformCapability(PlatformFeature.RewardedAds,support,availability,"mock.ads",CapabilityConstraints.ForegroundOnly|CapabilityConstraints.UserGestureRequired,1)});
    sealed class Journal:IAdReceiptJournal
    {
        internal readonly AdReceiptJournal Store=new AdReceiptJournal();internal bool Fail,Throw;internal int Count;
        public Result Record(AdPresentationReceipt receipt){Count++;if(Throw)throw new InvalidOperationException();return Fail?Result.Failure(Error("journal.injected",ErrorKind.Storage)):Store.Record(receipt);}
    }
    sealed class Env
    {
        internal readonly MockPlatformBackend PlatformBackend=new MockPlatformBackend();internal readonly MockRewardedAdBackend Backend=new MockRewardedAdBackend();internal readonly Journal Journal=new Journal();
        internal readonly PlatformService Platform;internal readonly AdsService Ads;internal readonly GameContext Context;
        internal Env(AdsLimits limits=null,string dependency="platform")
        {
            PlatformBackend.Startup=new PlatformStartup(Caps(),PlatformVisibility.Foreground);Platform=new PlatformService(PlatformBackend);Ads=new AdsService(Backend,Journal,limits,platformModuleId:dependency);
            Context=new GameContext(new[]{new ModuleRegistration("ads",Ads.Dependencies,()=>Ads,typeof(IAdsService)),new ModuleRegistration("platform",Platform.Dependencies,()=>Platform,typeof(IPlatformCapabilities),typeof(IPlatformLifecycle))},Cleanup);
        }
        internal MockRewardedAdAttempt Attempt=>Backend.Attempts[Backend.Attempts.Count-1];internal MockPlatformSession Session=>PlatformBackend.Sessions[0];
        internal async UniTask Start()=>Check(await Context.StartAsync(Wait));
        internal IAdOperation Capture(string claim="claim-A",ClaimOwnerSnapshot? owner=null){var r=Ads.Capture(Request(claim,owner));Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);return r.Value;}
        internal void Complete(MockRewardedAdAttempt a=null){a=a??Attempt;a.Publish(AdCallbackKind.Started);a.Publish(AdCallbackKind.Completed);a.Publish(AdCallbackKind.Closed);a.CompleteShow();}
        internal async UniTask Finish()
        {
            Backend.FailCleanup=Backend.ThrowCleanup=Backend.HoldCleanup=Journal.Fail=Journal.Throw=false;
            var close=Context.CloseAsync(Wait);
            for(var i=0;i<8;i++){foreach(var a in Backend.Attempts){a.CompleteLoad();a.CompleteShow();a.CompleteCleanup();}await UniTask.Yield();}
            var r=await close;if(!r.IsSuccess)r=await Context.RetryCleanupAsync(Cleanup,Wait);Check(r);Assert.AreEqual(0,Context.RetainedModuleCount);
        }
    }
    readonly List<Env> envs=new List<Env>();Env New(AdsLimits limits=null,string dependency="platform"){var e=new Env(limits,dependency);envs.Add(e);return e;}
    static void Check(Result r)=>Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);
    static async UniTask Frames(int n=5){for(var i=0;i<n;i++)await UniTask.Yield();}
    [UnityTearDown] public IEnumerator Teardown()=>UniTask.ToCoroutine(async()=>{Time.timeScale=1;foreach(var e in envs)await e.Finish();envs.Clear();});
    [UnityTest] public IEnumerator ConstructionAndCaptureRemainCold()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Capture();Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.AreEqual(AdPhase.Captured,e.Capture("second").Phase);});
    [UnityTest] public IEnumerator ContextInjectsAdsAfterPlatform()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.IsTrue(e.Context.TryGet<IAdsService>(out var ads));Assert.AreSame(e.Ads,ads);Assert.AreEqual(PlatformState.Ready,e.Platform.State);});
    [UnityTest] public IEnumerator CompletedFactRetainsOriginalCorrelationAndOwner()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();var r=await op.WaitAsync(Wait);Assert.IsTrue(r.IsSuccess);Assert.AreEqual(AdPhase.Completed,op.Phase);Assert.AreEqual(op.AttemptId,r.Value.AttemptId);Assert.IsTrue(r.Value.Owner.SameAs(Owner));Assert.AreEqual("claim-A",r.Value.ClaimId);Assert.AreEqual(1,e.Journal.Store.PendingCount);Assert.AreEqual(1,e.Attempt.CleanupCount);Assert.AreEqual(PlatformExecutionMode.Mock,r.Value.Mode);});
    [UnityTest] public IEnumerator SkippedIsSuccessfulObservationWithoutCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Skip=true;await e.Start();var r=await e.Capture().WaitAsync(Wait);Assert.IsTrue(r.IsSuccess);Assert.AreEqual(AdWatchOutcome.Skipped,r.Value.Outcome);Assert.IsFalse(r.Value.IsCompletionObserved);});
    [UnityTest] public IEnumerator NoFillRemainsDistinctAndNeverShows()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.LoadError=Error("mock.nofill",ErrorKind.NoFill);await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.NoFill,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(0,e.Attempt.ShowCount);Assert.AreEqual(AdWatchOutcome.Failed,op.Receipt.Outcome);Assert.AreEqual("",op.Receipt.Error.Value.Message);});
    [UnityTest] public IEnumerator NetworkFailureNeverAutomaticallyRetriesLoad()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.LoadError=Error("mock.network",ErrorKind.Network);await e.Start();Assert.AreEqual(ErrorKind.Network,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(1,e.Attempt.LoadCount);});
    [UnityTest] public IEnumerator FailedCallbackOverridesCompletionSignal()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Failed,error:Error("mock.callback"));e.Attempt.CompleteShow();Assert.AreEqual("mock.callback",(await t).Error.Code);Assert.IsFalse(op.Receipt.IsCompletionObserved);});
    [UnityTest] public IEnumerator ActualShowFailureOverridesCompletedCallbacks()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.ShowError=Error("mock.show");await e.Start();var op=e.Capture();Assert.AreEqual("mock.show",(await op.WaitAsync(Wait)).Error.Code);Assert.AreEqual(AdWatchOutcome.Failed,op.Receipt.Outcome);});
    [UnityTest] public IEnumerator MissingStartedOrClosedCannotComplete()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Completed);e.Attempt.CompleteShow();Assert.AreEqual(ErrorKind.Integrity,(await t).Error.Kind);Assert.IsFalse(op.Receipt.IsCompletionObserved);});
    [UnityTest] public IEnumerator EntireNativeLoadShowAndCleanupAreSerial()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var first=e.Capture();var t1=first.WaitAsync(Wait);var a=e.Attempt;var second=e.Capture("second");var t2=second.WaitAsync(Wait);await Frames();Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(AdPhase.Queued,second.Phase);a.CompleteShow();Assert.IsTrue((await t1).IsSuccess);await Frames();Assert.AreEqual(2,e.Backend.Attempts.Count);e.Attempt.CompleteShow();Assert.IsTrue((await t2).IsSuccess);Assert.AreEqual(1,a.CleanupCount);});
    [UnityTest] public IEnumerator FifoQueueSkipsCanceledEntryWithoutSdkWork()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var t1=e.Capture().WaitAsync(Wait);var a=e.Attempt;using(var c=new CancellationTokenSource()){var canceled=e.Capture("canceled");var t2=canceled.WaitAsync(OperationContext.Unlimited(c.Token));var third=e.Capture("third");var t3=third.WaitAsync(Wait);c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t2).Error.Kind);a.CompleteShow();await t1;await Frames();Assert.AreEqual(third.AttemptId,e.Attempt.AttemptId);e.Attempt.CompleteShow();Assert.IsTrue((await t3).IsSuccess);Assert.AreEqual(2,e.Backend.Attempts.Count);}});
    [UnityTest] public IEnumerator DuplicateClaimNeverReplaysPresentation()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Capture().WaitAsync(Wait);Assert.AreEqual("ads.claim.duplicate",(await e.Capture().WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ClaimCannotBeReassignedToNewOwner()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Capture().WaitAsync(Wait);var other=new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,"install-B",2,"local.b");Assert.AreEqual(ErrorKind.Integrity,(await e.Capture(owner:other).WaitAsync(Wait)).Error.Kind);Assert.AreEqual(1,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ClaimTrackingHasHardCapacity()=>UniTask.ToCoroutine(async()=>{var e=New(new AdsLimits(maxClaims:1));await e.Start();await e.Capture().WaitAsync(Wait);Assert.AreEqual("ads.claim.capacity",(await e.Capture("second").WaitAsync(Wait)).Error.Code);});
    [UnityTest] public IEnumerator WaitIsSingleUse()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();await op.WaitAsync(Wait);Assert.AreEqual("ads.wait.single_use",(await op.WaitAsync(Wait)).Error.Code);});
    [UnityTest] public IEnumerator PreCanceledWaitDoesNotCreateSdkAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var c=new CancellationTokenSource()){c.Cancel();var op=e.Capture();Assert.AreEqual(ErrorKind.Canceled,(await op.WaitAsync(OperationContext.Unlimited(c.Token))).Error.Kind);Assert.AreEqual(AdPhase.NotShown,op.Phase);}Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ZeroDeadlineDoesNotCreateSdkAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(default)).Error.Kind);Assert.AreEqual(AdPhase.NotShown,op.Phase);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator CancelDuringLoadWaitsActualLoadAndNeverShows()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;await e.Start();using(var c=new CancellationTokenSource()){var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(1,e.Attempt.CancelCount);Assert.AreEqual(0,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Ads.ActiveAttemptCount);e.Attempt.CompleteLoad();await Frames();Assert.AreEqual(0,e.Attempt.ShowCount);Assert.AreEqual(AdWatchOutcome.NotShown,op.Receipt.Outcome);Assert.AreEqual(0,e.Ads.ActiveAttemptCount);}});
    [UnityTest] public IEnumerator LoadTimeoutDoesNotReleaseBeforeActualCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.AreEqual(1,e.Ads.ActiveAttemptCount);e.Attempt.CompleteLoad();await Frames();Assert.AreEqual(0,e.Attempt.ShowCount);});
    [UnityTest] public IEnumerator CancelDuringShowKeepsSlotAndRetainsLateFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();using(var c=new CancellationTokenSource()){var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(c.Token));var a=e.Attempt;c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);var next=e.Capture("next");var t2=next.WaitAsync(Wait);await Frames();Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(0,a.CancelCount);e.Complete(a);await Frames();Assert.AreEqual(AdObserverState.Canceled,op.ObserverState);Assert.IsTrue(op.Receipt.IsCompletionObserved);Assert.AreEqual(1,e.Journal.Store.PendingCount);e.Complete();Assert.IsTrue((await t2).IsSuccess);}});
    [UnityTest] public IEnumerator ShowTimeoutCannotTurnLateCompletionIntoObserverSuccess()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);e.Complete();await Frames();Assert.AreEqual(AdObserverState.TimedOut,op.ObserverState);Assert.IsTrue(op.Receipt.IsCompletionObserved);Assert.AreEqual(0,e.Attempt.CancelCount);});
    [UnityTest] public IEnumerator ViewScopeCloseDoesNotDropActiveAdCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var scope=new Scope("revive-view");var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(scope.LifetimeCancellation));await scope.CloseAsync(Cleanup);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.CompleteShow();await Frames();Assert.AreEqual(1,e.Attempt.CleanupCount);Assert.IsTrue(op.Receipt.Owner.SameAs(Owner));});
    [UnityTest] public IEnumerator HideDuringLoadPreventsShowAfterLoadCompletes()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Platform.Generation,1,PlatformLifecycleKind.Hidden));await Frames();e.Attempt.CompleteLoad();Assert.AreEqual(ErrorKind.Unavailable,(await t).Error.Kind);Assert.AreEqual(0,e.Attempt.ShowCount);});
    [UnityTest] public IEnumerator HideDuringVisibleAdDoesNotInvalidateItsCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Platform.Generation,1,PlatformLifecycleKind.Hidden));await Frames();e.Attempt.CompleteShow();Assert.IsTrue((await t).IsSuccess);Assert.IsTrue(op.Receipt.IsCompletionObserved);Assert.AreEqual(ErrorKind.Unavailable,e.Ads.Capture(Request("next")).Error.Kind);e.Session.Publish(PlatformCallback.LifecycleChanged(e.Platform.Generation,2,PlatformLifecycleKind.Shown));await Frames();Assert.IsTrue(e.Ads.Capture(Request("next")).IsSuccess);});
    [UnityTest] public IEnumerator ColdOperationRechecksCapabilityAtWait()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();e.Session.Publish(PlatformCallback.CapabilitiesChanged(e.Platform.Generation,1,Caps(CapabilitySupport.Unsupported,CapabilityAvailability.Unavailable)));await Frames();Assert.AreEqual(ErrorKind.NotSupported,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator DefaultMockNeverSilentlyEnablesAds()=>UniTask.ToCoroutine(async()=>{var e=New();e.PlatformBackend.Startup=new PlatformStartup(MockPlatformBackend.DefaultCapabilities(),PlatformVisibility.Foreground);await e.Start();Assert.AreEqual(ErrorKind.NotSupported,e.Ads.Capture(Request()).Error.Kind);});
    [UnityTest] public IEnumerator CapabilityPermissionAndGestureRemainDistinct()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(ErrorKind.InvalidArgument,e.Ads.Capture(Request(user:false)).Error.Kind);e.Session.Publish(PlatformCallback.CapabilitiesChanged(e.Platform.Generation,1,Caps(availability:CapabilityAvailability.PermissionDenied)));await Frames();Assert.AreEqual(ErrorKind.PermissionDenied,e.Ads.Capture(Request()).Error.Kind);});
    [UnityTest] public IEnumerator AccountScopedModeRemainsGatedUntilS411()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(ErrorKind.NotSupported,e.Ads.Capture(Request(owner:new ClaimOwnerSnapshot(ClaimOwnerMode.AccountScoped,"account",1,"account.a"))).Error.Kind);});
    [UnityTest] public IEnumerator CloseDuringLoadWaitsAndNeverShows()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;await e.Start();var t=e.Capture().WaitAsync(Wait);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(0,e.Session.CleanupCount);e.Attempt.CompleteLoad();Check(await close);Assert.AreEqual(0,e.Attempt.ShowCount);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);});
    [UnityTest] public IEnumerator CloseAcceptsLateShowCallbacksAndRetainsDependencies()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.AreEqual(0,e.Session.CleanupCount);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Complete();Check(await close);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.IsTrue(op.Receipt.IsCompletionObserved);Assert.AreEqual(1,e.Journal.Store.PendingCount);Assert.AreEqual(1,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator CloseObserverTimeoutDoesNotForceNativeRelease()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);Assert.AreEqual(ErrorKind.Timeout,(await e.Context.CloseAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.AreEqual(0,e.Attempt.CleanupCount);Assert.Greater(e.Context.RetainedModuleCount,0);e.Attempt.CompleteShow();Check(await e.Context.CloseAsync(Wait));Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.IsTrue(op.Receipt.IsCompletionObserved);});
    [UnityTest] public IEnumerator DuplicateCallbacksDoNotDuplicateReceipt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);var a=e.Attempt;a.Publish(AdCallbackKind.Started,1);a.Publish(AdCallbackKind.Started,1);a.Publish(AdCallbackKind.Completed,2);a.Publish(AdCallbackKind.Completed,3);a.Publish(AdCallbackKind.Closed,4);a.CompleteShow();Assert.IsTrue((await t).IsSuccess);Assert.AreEqual(1,e.Journal.Count);Assert.Greater(e.Ads.DiscardedCallbacks,0);});
    [UnityTest] public IEnumerator WrongGenerationAndAttemptCannotCompleteAd()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Completed,generation:"old");e.Attempt.Publish(AdCallbackKind.Completed,attemptId:"wrong");await Frames();Assert.AreEqual(UniTaskStatus.Pending,t.Status);e.Complete();Assert.IsTrue((await t).IsSuccess);Assert.AreEqual(2,e.Ads.DiscardedCallbacks);});
    [UnityTest] public IEnumerator OldSequenceCannotRewriteSkippedOutcome()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Started,2);e.Attempt.Publish(AdCallbackKind.Completed,1);e.Attempt.Publish(AdCallbackKind.Closed,3);e.Attempt.CompleteShow();Assert.AreEqual(AdWatchOutcome.Skipped,(await t).Value.Outcome);});
    [UnityTest] public IEnumerator ClosedThenCompletedBeforeActualTerminalIsAccepted()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Started);e.Attempt.Publish(AdCallbackKind.Closed);e.Attempt.Publish(AdCallbackKind.Completed);e.Attempt.CompleteShow();Assert.IsTrue((await t).Value.IsCompletionObserved);});
    [UnityTest] public IEnumerator AfterTerminalFenceCannotUpgradeSkippedFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Skip=true;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);var a=e.Attempt;a.CompleteShow();e.Ads.TryPost(new AdCallback(e.Ads.Generation,op.AttemptId,4,AdCallbackKind.Completed));Assert.AreEqual(AdWatchOutcome.Skipped,(await t).Value.Outcome);await Frames();Assert.AreEqual(AdWatchOutcome.Skipped,op.Receipt.Outcome);Assert.IsFalse(a.Publish(AdCallbackKind.Completed));});
    [UnityTest] public IEnumerator WorkerCallbacksOnlyDispatchOnMainThread()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);var a=e.Attempt;await Task.Run(()=>{a.Publish(AdCallbackKind.Started);a.Publish(AdCallbackKind.Completed);a.Publish(AdCallbackKind.Closed);}).AsUniTask();Assert.IsTrue(PlayerLoopHelper.IsMainThread);a.CompleteShow();Assert.IsTrue((await t).Value.IsCompletionObserved);});
    [UnityTest] public IEnumerator PausedTimeScaleStillProcessesTimeoutAndLateReceipt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();Time.timeScale=0;var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);e.Attempt.CompleteShow();await Frames();Assert.IsTrue(op.Receipt.IsCompletionObserved);Assert.AreEqual(0,e.Ads.PendingCount);});
    [UnityTest] public IEnumerator BoundedInboxRejectsExcessWithoutInventingCompletion()=>UniTask.ToCoroutine(async()=>{var e=New(new AdsLimits(queueCapacity:2,callbacksPerFrame:1));e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);Assert.IsTrue(e.Attempt.Publish(AdCallbackKind.Started));Assert.IsTrue(e.Attempt.Publish(AdCallbackKind.Completed));Assert.IsFalse(e.Attempt.Publish(AdCallbackKind.Closed));e.Attempt.CompleteShow();Assert.AreEqual(ErrorKind.Integrity,(await t).Error.Kind);Assert.AreEqual(1,e.Ads.RejectedCallbacks);});
    [UnityTest] public IEnumerator CallbackFenceWaitsAcrossPerFrameBudget()=>UniTask.ToCoroutine(async()=>{var e=New(new AdsLimits(callbacksPerFrame:1));await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);Assert.AreEqual(UniTaskStatus.Pending,t.Status);Assert.IsTrue((await t).Value.IsCompletionObserved);Assert.AreEqual(0,e.Ads.QueuedCount);});
    [UnityTest] public IEnumerator FailedFactRetentionBlocksNextShowUntilExplicitRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Journal.Fail=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Storage,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(AdPhase.PendingFinalization,op.Phase);Assert.AreEqual(0,e.Attempt.CleanupCount);var first=e.Attempt;var t=e.Capture("second").WaitAsync(Wait);await Frames();Assert.AreEqual(1,e.Backend.Attempts.Count);e.Journal.Fail=false;Check(await e.Ads.RetryFinalizationAsync(Cleanup,Wait));Assert.IsTrue((await t).IsSuccess);Assert.AreEqual(1,first.ShowCount);Assert.AreEqual(2,e.Journal.Store.PendingCount);});
    [UnityTest] public IEnumerator CleanupFailureRetriesOnlyReleaseNeverShowOrFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.FailCleanup=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.CleanupFailed,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(1,e.Journal.Count);Assert.AreEqual(1,e.Ads.ActiveAttemptCount);e.Backend.FailCleanup=false;Check(await e.Ads.RetryFinalizationAsync(Cleanup,Wait));Assert.AreEqual(2,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Attempt.ShowCount);Assert.AreEqual(1,e.Journal.Count);Assert.AreEqual(0,e.Ads.PendingCount);});
    [UnityTest] public IEnumerator ContextCleanupDoesNotImplicitlyRetryFailedRelease()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.FailCleanup=true;await e.Start();await e.Capture().WaitAsync(Wait);Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);Assert.AreEqual(1,e.Attempt.CleanupCount);Assert.AreEqual(0,e.Session.CleanupCount);Assert.AreEqual(2,e.Context.RetainedModuleCount);e.Backend.FailCleanup=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator OriginalDisplayErrorSurvivesFinalizationFailure()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.LoadError=Error("original.no_fill",ErrorKind.NoFill);e.Backend.FailCleanup=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.NoFill,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(ErrorKind.CleanupFailed,op.FinalizationError.Value.Kind);Assert.AreEqual(ErrorKind.NoFill,op.Receipt.Error.Value.Kind);});
    [UnityTest] public IEnumerator JournalExceptionRetainsFactForExplicitRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Journal.Throw=true;await e.Start();var op=e.Capture();Assert.AreEqual("ads.receipt.exception",(await op.WaitAsync(Wait)).Error.Code);Assert.IsTrue(op.Receipt.IsCompletionObserved);e.Journal.Throw=false;Check(await e.Ads.RetryFinalizationAsync(Cleanup,Wait));Assert.AreEqual(1,e.Attempt.ShowCount);});
    [UnityTest] public IEnumerator ProviderExceptionsDoNotBecomeCancellation()=>UniTask.ToCoroutine(async()=>{foreach(var phase in new[]{"factory","load","show"}){var e=New();e.Backend.ThrowCreate=phase=="factory";e.Backend.ThrowLoad=phase=="load";e.Backend.ThrowShow=phase=="show";await e.Start();Assert.AreEqual(ErrorKind.Provider,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.AreEqual(0,e.Ads.PendingCount);}});
    [UnityTest] public IEnumerator CleanupExceptionRetainsOwnedAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.ThrowCleanup=true;await e.Start();var op=e.Capture();Assert.AreEqual("ads.cleanup.exception",(await op.WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Ads.ActiveAttemptCount);e.Backend.ThrowCleanup=false;Check(await e.Ads.RetryFinalizationAsync(Cleanup,Wait));Assert.AreEqual(1,e.Attempt.LoadCount);});
    [UnityTest] public IEnumerator CancelLoadFailureCannotReleaseActualLoad()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;e.Backend.FailCancel=true;await e.Start();using(var c=new CancellationTokenSource()){var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();await t;Assert.IsTrue(op.CancelError.HasValue);Assert.AreEqual(1,e.Ads.ActiveAttemptCount);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.CompleteLoad();await Frames();Assert.AreEqual(0,e.Attempt.ShowCount);}});
    [UnityTest] public IEnumerator CapacityRecoversAfterColdCancellation()=>UniTask.ToCoroutine(async()=>{var e=New(new AdsLimits(maxOperations:1));await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Unavailable,e.Ads.Capture(Request("other")).Error.Kind);await op.WaitAsync(default);Assert.IsTrue(e.Ads.Capture(Request("other")).IsSuccess);});
    [UnityTest] public IEnumerator OldContextCannotDeliverIntoNewContext()=>UniTask.ToCoroutine(async()=>{var old=New();await old.Start();var op=old.Capture();await op.WaitAsync(Wait);Check(await old.Context.CloseAsync(Wait));var next=New();next.Backend.AutoCallbacks=false;next.Backend.HoldShow=true;await next.Start();var current=next.Capture();var t=current.WaitAsync(Wait);Assert.IsFalse(old.Ads.TryPost(new AdCallback(old.Ads.Generation,op.AttemptId,90,AdCallbackKind.Completed)));next.Ads.TryPost(new AdCallback(old.Ads.Generation,current.AttemptId,90,AdCallbackKind.Completed));next.Complete();Assert.IsTrue((await t).Value.IsCompletionObserved);Assert.AreNotEqual(old.Ads.Generation,next.Ads.Generation);Assert.IsTrue(op.Receipt.Owner.SameAs(Owner));});
    [UnityTest] public IEnumerator CloseDrainsDiagnosticsButDoesNotEraseCallerJournal()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();for(var i=0;i<5;i++)await e.Capture("claim-"+i).WaitAsync(Wait);Check(await e.Context.CloseAsync(Wait));var d=e.Ads.ReadDiagnostics();Assert.AreEqual(0,d.PendingOperations);Assert.AreEqual(0,d.QueuedCallbacks);Assert.AreEqual(0,d.FailedCleanup);Assert.AreEqual(5,e.Journal.Store.PendingCount);Assert.IsTrue(e.Ads.IsClosed);});
    [UnityTest] public IEnumerator MissingPlatformDependencyFailsBeforeSdkWork()=>UniTask.ToCoroutine(async()=>{var e=New(dependency:"missing");Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator DescriptorMismatchRollsBackBeforeAdsWork()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Descriptor=new PlatformDescriptor("different",PlatformExecutionMode.Mock,"v1");Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ExplicitRetryIsSingleFlightAndObserverCancellationDoesNotAbortIt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.FailCleanup=true;await e.Start();await e.Capture().WaitAsync(Wait);e.Backend.FailCleanup=false;e.Backend.HoldCleanup=true;using(var c=new CancellationTokenSource()){var retry=e.Ads.RetryFinalizationAsync(Cleanup,OperationContext.Unlimited(c.Token));var join=e.Ads.RetryFinalizationAsync(Cleanup,Wait);c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await retry).Error.Kind);Assert.AreEqual(2,e.Attempt.CleanupCount);e.Attempt.CompleteCleanup();Check(await join);Assert.AreEqual(1,e.Attempt.ShowCount);Assert.AreEqual(0,e.Ads.PendingCount);}});
    [UnityTest] public IEnumerator QueueTimeoutNeverConsumesNativeAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();var t=e.Capture().WaitAsync(Wait);var first=e.Attempt;var queued=e.Capture("queued");Assert.AreEqual(ErrorKind.Timeout,(await queued.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);first.CompleteShow();await t;await Frames();Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.IsNull(queued.Receipt);});
    [UnityTest] public IEnumerator RetryWithoutRetainedWorkDoesNotReplayAd()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Capture().WaitAsync(Wait);Assert.AreEqual(ErrorKind.InvalidState,(await e.Ads.RetryFinalizationAsync(Cleanup,Wait)).Error.Kind);Assert.AreEqual(1,e.Attempt.ShowCount);});
    [UnityTest] public IEnumerator QueueRemainsBlockedWhileActualCleanupIsPending()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldCleanup=true;await e.Start();var first=e.Capture();var t1=first.WaitAsync(Wait);await Frames();Assert.AreEqual(AdPhase.Draining,first.Phase);var a=e.Attempt;var t2=e.Capture("next").WaitAsync(Wait);await Frames();Assert.AreEqual(1,e.Backend.Attempts.Count);e.Backend.HoldCleanup=false;a.CompleteCleanup();Assert.IsTrue((await t1).IsSuccess);Assert.IsTrue((await t2).IsSuccess);Assert.AreEqual(2,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator OwnerSnapshotDoesNotFollowExternalIdentityChange()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var current=Owner;var op=e.Capture(owner:current);var t=op.WaitAsync(Wait);current=new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,"install-B",8,"local.b");e.Complete();var r=await t;Assert.IsTrue(r.Value.Owner.SameAs(Owner));Assert.IsFalse(r.Value.Owner.SameAs(current));});
    [UnityTest] public IEnumerator CompletionBeforeStartedCannotInventValidPresentation()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.AutoCallbacks=false;e.Backend.HoldShow=true;await e.Start();var op=e.Capture();var t=op.WaitAsync(Wait);e.Attempt.Publish(AdCallbackKind.Completed);e.Attempt.Publish(AdCallbackKind.Started);e.Attempt.Publish(AdCallbackKind.Closed);e.Attempt.CompleteShow();Assert.AreEqual("ads.callback.order",(await t).Error.Code);Assert.IsFalse(op.Receipt.IsCompletionObserved);});
